insert into REP_INVESTDETAIL ( SEQNO, PROD_ID, VAL_DATE, ASSET_TYPE_CODE, ASSETS_VALUE_NET, ASSETS_VALUE_NET_SCALE, IS_SCALE_OUT, STATUS, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) select A.* from (
select #{item.seqno,jdbcType=VARCHAR}, #{item.prodId,jdbcType=VARCHAR}, #{item.valDate,jdbcType=DATE}, #{item.assetTypeCode,jdbcType=VARCHAR}, #{item.assetsValueNet,jdbcType=DECIMAL}, #{item.assetsValueNetScale,jdbcType=DECIMAL}, #{item.isScaleOut,jdbcType=CHAR}, #{item.status,jdbcType=CHAR}, #{item.createUser,jdbcType=VARCHAR}, #{item.createDept,jdbcType=VARCHAR}, #{item.createTime,jdbcType=TIMESTAMP}, #{item.updateUser,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=TIMESTAMP} from sysibm.SYSDUMMY1
)A
